Rules.InvariantScript:
Reset(chkMedicalEmergency);
Reset(chkInjury);
Reset(chkFire);
Reset(chkBreathingIssue);
Reset(chkSecurityThreat);
Reset(chkChestPain)

Set(
    vAssignedResponder,
    Index(
        [
            "Daniel Brooks",
            "Sophie Turner",
            "Ryan Mitchell",
            "Emily Carter",
            "Ben Walker",
            "Grace Wilson",
            "Liam Parker",
            "Chloe Bennett"
        ],
        RandBetween(1, 8)
    ).Value
);

Set(
    vEstimatedTimeArrival,
    RandBetween(1, 15)
);

Set(
    vResponderMessage,
    Index(
        [
            "I am on my way. Please stay calm.",
            "I have received your request and I am heading to you now.",
            "Help is coming. Try to stay where you are.",
            "I am nearby and will arrive shortly.",
            "Please remain calm. I am responding to your emergency.",
            "I can see your request. I am on the way now."
        ],
        RandBetween(1, 6)
    ).Value
);

Set(
    vPatientRequest,
    Patch(
        PatientRequests,
        LookUp(PatientRequests, ID = vPatientRequest.ID),
        {
            AssignedResponder: vAssignedResponder,
            EstimatedTimeArrival: vEstimatedTimeArrival,
            ResponderMessage: vResponderMessage,
            RequestStatus: {Value: "Found responder"}
        }
    )
);

Navigate(Rescueconfirmed, ScreenTransition.Fade)

ClearCollect(
    selectedEmergencyTypes,
    If(chkMedicalEmergency.Checked, {Value: "Medical emergency"}),
    If(chkInjury.Checked, {Value: "Injury"}),
    If(chkFire.Checked, {Value: "Fire"}),
    If(chkBreathingIssue.Checked, {Value: "Breathing issue"}),
    If(chkSecurityThreat.Checked, {Value: "Security threat"}),
    If(chkChestPain.Checked, {Value: "Chest pain"})
);

ClearCollect(
    selectedEmergencyTypes,
    Filter(selectedEmergencyTypes, !IsBlank(Value))
);

If(
    CountRows(selectedEmergencyTypes) = 0,
    Notify("Please select at least one emergency type.", NotificationType.Error),

    If(
        IsBlank(txtPatientCondition.Text),
        Notify("Please describe your medical condition.", NotificationType.Error),

        Set(
            vPatientRequest,
            Patch(
                PatientRequests,
                Defaults(PatientRequests),
                {
                    Title: "Patient Request",
                    EmergencyType: selectedEmergencyTypes,
                    MedicalCondition: txtPatientCondition.Text
                }
            )
        );

        Notify("Emergency information saved", NotificationType.Success);


    )
)
